import assert from "node:assert/strict";
import test from "node:test";
import { createRequire, registerHooks } from "node:module";
import { $ } from "@builder.io/qwik";

// These routing modules are generated by Vite; validation does not use them.
registerHooks({
  resolve(specifier, context, nextResolve) {
    if (
      specifier === "@qwik-city-plan" ||
      specifier === "@qwik-city-sw-register"
    ) {
      return {
        url: new URL("./fixtures/routing.cjs", import.meta.url).href,
        shortCircuit: true,
      };
    }
    return nextResolve(specifier, context);
  },
});
const { z, zodQrl } = await import("@builder.io/qwik-city");

test("the CommonJS Qwik validator supports the patched Zod integration", async () => {
  const city = createRequire(import.meta.url)("@builder.io/qwik-city");
  const validator = city.zodQrl(
    $(city.z.object({ name: city.z.string().min(1) })),
  );
  const result = await validator.validate({}, { name: "" });
  assert.equal(result.success, false);
  assert.ok(result.error.fieldErrors.name);
});

test("Qwik validates record schemas and preserves form coercion", async () => {
  const validator = zodQrl(
    $({
      count: z.coerce.number().int().min(1),
      enabled: z.preprocess((value) => value === "on", z.boolean()),
    }),
  );
  const result = await validator.validate({}, { count: "3", enabled: "on" });
  assert.equal(result.success, true);
  assert.deepEqual(result.data, { count: 3, enabled: true });
});

test("Qwik returns field errors for invalid input", async () => {
  const validator = zodQrl($({ count: z.coerce.number().int().min(1) }));
  const result = await validator.validate({}, { count: "0" });
  assert.equal(result.success, false);
  assert.equal(result.status, 400);
  assert.ok(result.error.fieldErrors.count);
  assert.deepEqual(result.error.formErrors, []);
});

test("Qwik accepts a complete Zod schema and reports root errors", async () => {
  const validator = zodQrl($(z.object({ name: z.string() })));
  const result = await validator.validate({}, []);
  assert.equal(result.success, false);
  assert.equal(result.status, 400);
  assert.ok(result.error.formErrors.length);
});

test("Qwik resolves schema factories and parses the request body", async () => {
  const validator = zodQrl($((schema) => ({ name: schema.string().min(1) })));
  const result = await validator.validate({
    parseBody: async () => ({ name: "test" }),
  });
  assert.equal(result.success, true);
  assert.deepEqual(result.data, { name: "test" });
});

test("Qwik retains nested array field error paths", async () => {
  const validator = zodQrl(
    $({ links: z.array(z.object({ url: z.string().url() })).max(5) }),
  );
  const result = await validator.validate({}, { links: [{ url: "invalid" }] });
  assert.equal(result.success, false);
  assert.ok(result.error.fieldErrors["links[].url"].length);
});
